import type { CycleSummary, DebtRow, InstallmentRow, PaymentRow } from './schemas';

export interface DebtDetail {
  debt: DebtRow;
  memo: string | null;
  category: string | null;
  payments: PaymentRow[];
  installments: InstallmentRow[];
}

/** A payment to record. `id` is generated by the client and reused on retry (idempotency key). */
export interface NewPayment {
  id: string;
  debtId: string;
  paidOn: string;
  amountIdr: number;
  reference: string | null;
  note: string | null;
}

/** A reversal entry: written as a NEW negative ledger row that points at the payment it cancels. */
export interface NewReversal {
  id: string;
  debtId: string;
  reversesPaymentId: string;
  /** The original payment's (positive) amount; the entry is stored as its exact negative. */
  amountIdr: number;
  paidOn: string;
  note: string | null;
}

export class NotFoundError extends Error {
  constructor(what: string) {
    super(`NOT_FOUND: ${what}`);
    this.name = 'NotFoundError';
  }
}

/**
 * Satu-satunya pintu data untuk UI. Perhitungan (status, siklus, sisa) berasal dari SQL
 * (`debt_list`, `cycle_summary`); implementasi hanya mengambil dan memvalidasi.
 * Dua implementasi: fixture (dibangkitkan dari SQL asli; hanya mode `--mode fixture`) dan Supabase.
 */
export interface DataSource {
  readonly kind: 'fixture' | 'supabase';
  /** The active book. Every number on one screen comes from a single book. */
  readonly bookId: string;
  /** Tanggal hari ini (ISO) menurut zona waktu buku. */
  getToday(): string;
  cycleSummary(): Promise<CycleSummary>;
  debts(): Promise<DebtRow[]>;
  debtDetail(debtId: string): Promise<DebtDetail>;
  inboxPendingCount(): Promise<number>;
  /** Appends a payment to the ledger. Throws PaymentWriteError. Ledger rows are never updated or deleted. */
  recordPayment(payment: NewPayment): Promise<void>;
  /** Appends a reversal entry. Throws PaymentWriteError. */
  reversePayment(reversal: NewReversal): Promise<void>;
}
